"""Print the real held-out evaluation report generated by DCRNN training."""
import json
from app.core.config import get_settings

def evaluate() -> dict:
    path=get_settings().artifact_dir/"metrics.json"
    if not path.is_file():
        raise FileNotFoundError("No held-out evaluation found. Run `python -m app.ml.train` to train and evaluate DCRNN.")
    report=json.loads(path.read_text(encoding="utf-8"))
    print(json.dumps(report,indent=2))
    return report

if __name__=="__main__": evaluate()
